/* Fortran ARNAUD_dnaupd / dneupd. We'll declare with the classic ARPACK signature
   which ARNAUD is drop-in compatible with. */

extern void ARNAUD_dnaupd(
    int *ido, char *bmat, int *n, char *which, int *nev, double *tol,
    double *resid, int *ncv, double *v, int *ldv, int *iparam, int *ipntr,
    double *workd, double *workl, int *lworkl, int *info
);

extern void ARNAUD_dneupd(
