    st.which = 0; /* LM */
    st.bmat = 0;  /* I */
    st.info = 1;  /* resid supplied */
    st.maxiter = maxiter;
    st.mode = 1;
    st.n = n;
    st.ncv = ncv;
    st.nev = k;
    st.shift = 1;

