    int guard = 0;
    int limit = maxiter * (ncv + 2) + 50;
    while (guard++ < limit) {
        dnaupd(&st, resid, v, lworkl, ipntr, workd, workl);
        int ido = st.ido;
        if (ido == 1 || ido == -1 || ido == 5) {
            int x0 = ipntr[0] - 1;
            int y0 = ipntr[1] - 1;
